            modelBuilder.Entity("Waterly.Api.Models.DailyActivity", b =>
                {
                    b.Property<Guid>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("uuid");

                    b.Property<decimal?>("ActiveCalories")
                        .HasPrecision(8, 2)
                        .HasColumnType("numeric(8,2)");

                    b.Property<DateOnly>("Date")
                        .HasColumnType("date");

                    b.Property<int>("ExerciseMinutes")
                        .HasColumnType("integer");

                    b.Property<string>("Source")
                        .IsRequired()
                        .HasMaxLength(32)
                        .HasColumnType("character varying(32)");

                    b.Property<int>("Steps")
                        .HasColumnType("integer");

                    b.Property<DateTimeOffset>("UpdatedAt")
                        .HasColumnType("timestamp with time zone");

                    b.Property<Guid>("UserId")
                        .HasColumnType("uuid");

                    b.HasKey("Id");

                    b.HasIndex("UserId", "Date", "Source")
                        .IsUnique();

                    b.ToTable("DailyActivities", null, t =>
                        {
                            t.HasCheckConstraint("CK_DailyActivities_ExerciseMinutes", "\"ExerciseMinutes\" >= 0 AND \"ExerciseMinutes\" <= 1440");

                            t.HasCheckConstraint("CK_DailyActivities_Steps", "\"Steps\" >= 0");
                        });
                });

